import sys

class Node:
    def __init__(self, key):
        self.key = key
        self.left = self.right = None
        self.height = 1

def height(p):
    return p.height if p else 0

def update(p):
    p.height = 1 + max(height(p.left), height(p.right))

def rotate_right(p):
    q = p.left
    p.left = q.right
    q.right = p
    update(p)
    update(q)
    return q

def rotate_left(p):
    q = p.right
    p.right = q.left
    q.left = p
    update(p)
    update(q)
    return q

def insert(p, key):
    if p is None:
        return Node(key)
    if key < p.key:
        p.left = insert(p.left, key)
    elif key > p.key:
        p.right = insert(p.right, key)
    else:
        return p
    update(p)
    balance = height(p.left) - height(p.right)
    if balance > 1:
        if key > p.left.key:
            p.left = rotate_left(p.left)
        return rotate_right(p)
    if balance < -1:
        if key < p.right.key:
            p.right = rotate_right(p.right)
        return rotate_left(p)
    return p

data = list(map(int, sys.stdin.buffer.read().split()))
root = None
for key in data[1:1 + data[0]]:
    root = insert(root, key)
print(root.key)
